import { mkdirSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { pathToFileURL } from 'node:url';
import { createHash } from 'node:crypto';
const server = "E:\\odin\\.odin\\validation-tools\\typescript\\node_modules\\typescript-language-server\\lib\\cli.mjs";
const expectedSha256 = "192638f1fa62c907fd54c0b55b12dd3dff01325a1a0ed5973907efca1c57b5eb";
mkdirSync(tmpdir(), { recursive: true });
if (createHash('sha256').update(readFileSync(server)).digest('hex') !== expectedSha256) {
  throw new Error('Trusted TypeScript server module hash mismatch');
}
process.argv = [process.execPath, server, '--stdio'];
await import(pathToFileURL(server).href);

